include <robotics.scad>
// Benewake TFmini-S housing. Origin: floor centre; back face at y=+8, lenses face -Y.
// Official (datasheet p.2): envelope 42 x 15 x 16, body 33 x 15 x 11 deep,
// ears 5 deep from back face, 2x Ø2.35 at 36 c-c on mid-height line,
// lens bosses Ø9.4 / Ø10.4, centres 10 apart, outer span 19.9, on mid-height.
$fn = 64;
L_all = 42;  L_body = 33;  H = 15;
D_all = 16;  D_body = 11;  D_ear = 5;
hole_d = 2.35;  hole_cc = 36;
y_back = D_all/2;                    // +8
y_face = y_back - D_body;            // -3 body front face
y_tip  = -D_all/2;                   // -8 boss tips
zc = H/2;                            // 7.5 optical / hole centre line
d1 = 9.4;  d2 = 10.4;  lens_cc = 10;
x1 = -19.9/2 + d1/2;                 // -5.25 (Ø9.4, drawing-left = -X)
x2 = x1 + lens_cc;                   //  4.75 (Ø10.4)
// NOT dimensioned (kept plain): ear height, edge radius, lens recess
ear_h = L_all - hole_cc;             // 6 = 2 x R3 end radius implied by 42/36
r_edge = 0.8;
rec_depth = 1.5;  rec_wall = 1.0;

difference() {
  union() {
    // main body 33 x 11 x 15
    translate([0, y_back - D_body/2, H/2])
      cuboid([L_body, D_body, H], rounding = r_edge);
    // ears: R3 ends about the holes, 5 deep from the back face
    translate([0, y_back, zc]) rotate([90, 0, 0])
      linear_extrude(height = D_ear)
        for (s = [-1, 1]) hull() {
          translate([s*hole_cc/2, 0]) circle(d = ear_h);
          translate([s*(L_body/2 - 1), 0]) square([2, ear_h], center = true);
        }
    // lens bosses, 5 proud of the body front face (+Z rotated to -Y)
    for (b = [[x1, d1], [x2, d2]])
      translate([b[0], y_face + 0.01, zc]) rotate([90, 0, 0])
        cylinder(d = b[1], h = y_face - y_tip + 0.01);
  }
  // mounting holes Ø2.35 through the ears
  for (s = [-1, 1])
    translate([s*hole_cc/2, y_back + 1, zc]) rotate([90, 0, 0])
      cylinder(d = hole_d, h = D_ear + 2);
  // shallow lens recesses (depth not dimensioned)
  for (b = [[x1, d1], [x2, d2]])
    translate([b[0], y_tip - 0.01, zc]) rotate([-90, 0, 0])
      cylinder(d = b[1] - 2*rec_wall, h = rec_depth + 0.01);
}

include <robotics.scad>
// Lens window, origin at window centre on its front face; faces -Y.
$fn = 64;
d = 9.4 - 2*1.0 - 0.02;   // recess bore minus a hair
t = 0.8;
rotate([-90, 0, 0]) cylinder(d = d, h = t);

include <robotics.scad>
// Lens window, origin at window centre on its front face; faces -Y.
$fn = 64;
d = 10.4 - 2*1.0 - 0.02;
t = 0.8;
rotate([-90, 0, 0]) cylinder(d = d, h = t);
